using System;
using System.Collections.Generic;
using UnityEngine;
namespace SpeedStars.Themes {
 public sealed partial class ThemedLoopWay {
  readonly List<RomanStreetSectionPlan> marinePlans=new List<RomanStreetSectionPlan>();
  readonly Dictionary<string,int> marineUsage=new Dictionary<string,int>();readonly Queue<string> marineRecent=new Queue<string>();
  void ResetMarineLayout(){marinePlans.Clear();marineUsage.Clear();marineRecent.Clear();}
  GameObject MarinePick(System.Random random,RomanStreetSectionPlan plan){var choices=new List<GameObject>();int best=int.MaxValue;for(int pass=0;pass<2&&choices.Count==0;pass++)foreach(var p in theme.landmarks){if(!p)continue;bool already=false;foreach(var b in plan.buildings)if(b.asset==p)already=true;if(already||(pass==0&&marineRecent.Contains(p.name)))continue;int n;marineUsage.TryGetValue(p.name,out n);if(n<best){best=n;choices.Clear();}if(n==best)choices.Add(p);}return choices.Count>0?choices[random.Next(choices.Count)]:null;}
  void MarinePlan(int index){while(marinePlans.Count<=index){int n=marinePlans.Count;float a=StartZ+n*SectionLength,b=a+SectionLength;var random=new System.Random(Hash(seed,n+7503));var plan=new RomanStreetSectionPlan();float cursor=a+R(random,1,5);int cluster=random.Next(1,3);
    while(cursor<b-5&&plan.buildings.Count<DepthBuildingBudget(n)){var asset=MarinePick(random,plan);if(!asset)break;float yaw=270+R(random,-9,9);var native=MeasuredRomanBounds(asset,Vector3.one,yaw);float scale=R(random,.85f,1.08f);scale=Mathf.Min(scale,R(random,4.3f,4.9f)/Mathf.Max(1,native.max.y));scale=Mathf.Min(scale,12.5f/Mathf.Max(1,native.size.z));scale*=DepthPhrasePhase(n)==4?.88f:.76f;var size=Vector3.one*scale;var bounds=MeasuredRomanBounds(asset,size,yaw);if(cursor+bounds.size.z>b-1)break;var placed=new RomanStreetPlacement{asset=asset,scale=size,yaw=yaw,bounds=bounds};
     // Pier piles stay submerged. Align the front edge without lifting the pier's sea-bed base.
     placed.position=new Vector3(DepthFront(n,plan.buildings.Count,R(random,-26,-24),R(random,-35,-31))-bounds.max.x,0,cursor-bounds.min.z);bounds.center+=placed.position;placed.bounds=bounds;plan.buildings.Add(placed);int uses;marineUsage.TryGetValue(asset.name,out uses);marineUsage[asset.name]=uses+1;marineRecent.Enqueue(asset.name);while(marineRecent.Count>4)marineRecent.Dequeue();cluster--;cursor=bounds.max.z+(cluster>0?R(random,7,12):R(random,20,31));if(cluster<=0)cluster=random.Next(1,3);
    }marinePlans.Add(plan);
   }}
  int MarineEventChoice(int cell){if(cell<8)return new[]{0,1,5,2,6,3,4,7}[cell]%theme.background.Length;int count=theme.background.Length;var deck=new List<int>();for(int i=0;i<count;i++)deck.Add(i);var random=new System.Random(Hash(seed,cell/count+571));for(int i=count-1;i>0;i--){int j=random.Next(i+1),t=deck[i];deck[i]=deck[j];deck[j]=t;}if(deck[0]==MarineEventChoice(cell-cell%count-1)){int t=deck[0];deck[0]=deck[1];deck[1]=t;}return deck[cell%count];}
  void BuildMarineLayout(Transform root,ThemeChunk chunk,float a,float b,int index,int sectionSeed){MarinePlan(index);var random=new System.Random(Hash(sectionSeed,341));var frontage=Group("Varied Working Waterfront",root);var names=new List<string>();foreach(var p in marinePlans[index].buildings){SpawnMeasuredRoman(p,frontage);names.Add(p.asset.name);float x0=-21.8f,x1=p.bounds.max.x-.35f,y0=.05f,y1=.51f*Mathf.Abs(p.scale.y),dx=x1-x0,dy=y1-y0;var ramp=Block(frontage,"Grounded Timber Gangway to Waterfront",new Vector3((x0+x1)*.5f,(y0+y1)*.5f-.07f,p.bounds.center.z),new Vector3(Mathf.Sqrt(dx*dx+dy*dy),.16f,2),theme.pathMaterial);ramp.transform.localRotation=Quaternion.Euler(0,0,Mathf.Atan2(dy,-dx)*-Mathf.Rad2Deg);}
   // Event centers live on a separate global grid, deliberately unrelated to section length.
   var scenery=Group("Cross Section Marine Coast and Story Events",root);const float span=75;int first=Mathf.FloorToInt((a-StartZ)/span)-1,last=Mathf.CeilToInt((b-StartZ)/span)+1;for(int cell=Mathf.Max(0,first);cell<=last;cell++){var r=new System.Random(Hash(seed,cell+919));float z=StartZ+cell*span+(cell==0?38:R(r,18,26));if(z<a||z>=b||theme.background.Length==0)continue;var asset=theme.background[MarineEventChoice(cell)];bool ship=asset.name.Contains("Galleon")||asset.name.Contains("Flagship"),boat=asset.name.Contains("Skiff"),arch=asset.name.Contains("Headland");float scale=ship?R(r,.6f,.78f):boat?R(r,.9f,1.25f):arch?R(r,.75f,1.05f):R(r,.92f,1.13f);float x=ship?R(r,-65,-56):boat?R(r,-47,-40):R(r,-75,-64);if(asset.name.Contains("Volcanic"))x=R(r,-89,-79);else if(asset.name.Contains("Crescent"))x=R(r,-63,-51);else if(arch)x=R(r,-51,-44);float yaw=270+R(r,ship?-7:-14,ship?7:14);var obj=Item(asset,scenery,new Vector3(x,0,z),yaw,scale);obj.name=asset.name+" - coastline event "+cell;ThemeAtmosphere.Set(obj,new Color(.64f,.79f,.85f),boat?.42f:.78f);
   }
   var lamps=Group("Continuous Harbor Lantern Rhythm",root);for(int i=Mathf.CeilToInt(a/20.67f);i*20.67f<b;i++)if(theme.lamps.Length>0)Item(theme.lamps[0],lamps,new Vector3(-16,0,i*20.67f),270,.66f);
   var props=Group("Harbor Equipment on Grounded Timber Plinths",root);var propRandom=new System.Random(Hash(seed,6382));var deck=new List<GameObject>(theme.props);for(int i=deck.Count-1;i>0;i--){int j=propRandom.Next(i+1);var p=deck[i];deck[i]=deck[j];deck[j]=p;}int count=1+index%2;for(int i=0;i<count&&deck.Count>0;i++){var asset=deck[((index/2)*7+(index%2)*3+i)%deck.Count];float yaw=270+R(random,-18,18),scale=R(random,.72f,.92f);var bounds=MeasuredRomanBounds(asset,Vector3.one*scale,yaw);if(bounds.size.y>2.3f)scale*=2.3f/bounds.size.y;bounds=MeasuredRomanBounds(asset,Vector3.one*scale,yaw);float z=a+(i+R(random,.25f,.75f))*(b-a)/count,x=-17.2f-bounds.max.x;bool flat=asset.name.Contains("Rope")||asset.name.Contains("Barrel")||asset.name.Contains("Crate");float h=flat?.35f:.55f;var pos=new Vector3(x,h-bounds.min.y,z-bounds.center.z);Item(asset,props,pos,yaw,scale);Block(props,"Grounded Equipment Timber Base",new Vector3(x+bounds.center.x,h*.5f,z),new Vector3(Mathf.Max(.9f,bounds.size.x+.18f),h,Mathf.Max(.9f,bounds.size.z+.18f)),theme.pathMaterial);}
   if(theme.clouds!=null&&theme.clouds.Length>0){var clouds=Group("Sparse Marine Horizon Clouds",root);int countCloud=random.Next(0,3);for(int i=0;i<countCloud;i++){var cloud=Item(theme.clouds[random.Next(theme.clouds.Length)],clouds,new Vector3(-100,R(random,8,11),a+(i+.5f)*(b-a)/Mathf.Max(1,countCloud)),270,R(random,.42f,.62f));var v=cloud.GetComponent<SpeedStars.Runner.CloudVariation>();if(v){v.shapeVariant=R(random,0,1000);v.Apply();}}}
   chunk.landmarkSummary="Working marine coast: "+string.Join(", ",names.ToArray());
  }
 }
}
